<div><p>{{ $summary }}</p>@if($url)<div x-data="{copied:false}"><label>Public campaign link<input x-ref="link" readonly value="{{ $url }}" style="width:100%;padding:.75rem;border:1px solid #888" @focus="$el.select()"></label><button type="button" x-on:click="navigator.clipboard ? navigator.clipboard.writeText($refs.link.value).then(()=>copied=true).catch(()=>$refs.link.select()) : $refs.link.select()" style="padding:.75rem;border:1px solid #888">Copy link</button><span x-show="copied" role="status">Copied</span></div><p>Sharing is your action. Opening the link does not add products, create orders or use the offer.</p>@else<p>This offer or its destination is not public. Activate it and choose a published collection or Shop.</p>@endif</div>